nta.declaration:
// =====================================================================
// Dispositivo IoT de alerta temprana de radiacion UV - Grupo 6
// Model Checking (UPPAAL 5.0) derivado del modelo VDM++ (Tipos,
// DispositivoUV y CentralMonitoreo).
// Comportamiento modelado: recepcion de una lectura UV en la central y
// ciclo de vida de la alerta que genera (Pendiente -> Emitida -> Atendida).
// =====================================================================

// ---- Constantes (Tipos`INDICE_MAX, Tipos`UMBRAL_ALERTA) ----
const int INDICE_MAX    = 20;
const int UMBRAL_ALERTA = 8;

// Lecturas que procesa el sistema (acota el espacio de estados)
const int MAX_LECT  = 4;
// En el peor caso todas las lecturas son de riesgo: una alerta por lectura
const int N_ALERTAS = MAX_LECT;

// Periodo de muestreo del sensor y plazo maximo para emitir una alerta
const int PERIODO   = 5;
const int T_EMITIR  = 2;

// Discretizacion del indice: valores frontera de cada clase de equivalencia
//  -1 y 21 fuera de rango | 0 y 7 sin riesgo | 8 umbral | 11 extremo | 20 maximo
const int NV = 7;
const int VALORES[NV] = {-1, 0, 7, 8, 11, 20, 21};

// ---- Tipos`EstadoSensor ----
const int OPERATIVO      = 0;
const int SIN_LECTURA    = 1;
const int FUERA_DE_RANGO = 2;

// ---- Tipos`NivelRiesgo ----
const int BAJO = 0;
const int MODERADO = 1;
const int ALTO = 2;
const int MUY_ALTO = 3;
const int EXTREMO = 4;

typedef int[0, N_ALERTAS-1] id_t;
typedef int[0, MAX_LECT-1]  lect_t;

// ---- Canales ----
chan leer;             // el sensor entrega una lectura a la central
chan crear[N_ALERTAS]; // la central crea la alerta i (A1)

// ---- Lectura en transito (Tipos`LecturaUV) ----
int  lec_indice = 0;
bool lec_senal  = false;

// ---- DispositivoUV`historial (instante = posicion en la secuencia) ----
int[0, MAX_LECT] n = 0;          // len historial
int hist_ind[MAX_LECT];          // indice de cada lectura
int hist_est[MAX_LECT];          // estado de cada lectura

// ---- CentralMonitoreo`alertas ----
int[0, N_ALERTAS] total = 0;     // card dom alertas
int  alerta_lect[N_ALERTAS];     // lectura que origino la alerta
int  alerta_nivel[N_ALERTAS];    // nivel de riesgo de la alerta
bool emitida[N_ALERTAS];         // la alerta paso por Emitida

// Tipos`Clasificar (RF5)
int clasificar(int i) {
    if (i < 3)  return BAJO;
    if (i < 6)  return MODERADO;
    if (i < 8)  return ALTO;
    if (i < 11) return MUY_ALTO;
    return EXTREMO;
}

// DispositivoUV`RegistrarLectura (RF4)
void registrar(int estado) {
    hist_ind[n] = lec_indice;
    hist_est[n] = estado;
    n++;
}

// CentralMonitoreo`RecibirLectura, rama EsRiesgo (RF6, RF7)
void crearAlerta() {
    alerta_lect[total]  = n - 1;
    alerta_nivel[total] = clasificar(lec_indice);
    total++;
}
